e:21px}.command b{display:block;margin:12px 0 5px;font:18px Georgia,serif}.command span{color:#93b3b8;font-size:12px}.workspace{margin-top:14px;padding:22px;border:1px solid var(--line);background:#04151def;min-height:430px}.workspace-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.workspace h2{margin:5px 0 18px;font:32px Georgia,serif}.filters{display:grid;grid-template-columns:minmax(220px,2fr) minmax(180px,1fr) auto;gap:10px;margin-bottom:14px}.cyber-input,.cyber-select{width:100%;min-height:44px;padding:9px 12px;border:1px solid #315d66;background:#03141b;color:#eafffa;outline:0}.cyber-input:focus,.cyber-select:focus{border-color:var(--cyan);box-shadow:0 0 0 3px #37fbd016}.cyber-select option{background:#082029}.cyber-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:9px 14px;border:1px solid #39717b;background:#0a2730;color:#eafffa;font-weight:800;text-decoration:none;cursor:pointer}.cyber-btn:hover{border-color:var(--cyan);color:var(--cyan)}.cyber-btn.primary{border-color:#20dcae;background:#19c99b;color:#021711}.cyber-btn.warn{border-color:#d1a943;color:#ffda78}.cyber-btn.danger{border-color:#b34a5d;color:#ff9baa}.cyber-btn.sm{min-height:34px;padding:6px 9px;font-size:12px}.data-wrap{overflow:auto;border:1px solid #2d5963}.data-grid{width:100%;border-collapse:collapse;white-space:nowrap}.data-grid th{padding:11px;background:#10313a;color:#83e8d0;font:700 11px monospace;letter-spacing:.08em;text-transform:uppercase}.data-grid td{padding:11px;border-top:1px solid #264b54;color:#d9ebe8;font-size:13px;vertical-align:middle}.data-grid tbody tr:hover{background:#0b2b34}.identity strong{display:block;color:#fff}.identity small{color:#799da1}.badge-node{display:inline-block;padding:4px 8px;border:1px solid #33856e;color:#72eac8;background:#123c32;font:700 10px monospace;text-transform:uppercase}.badge-node.off{border-color:#78505a;color:#ff9baa;background:#321b22}.actions{display:flex;gap:6px;flex-wrap:wrap}.empty-state{padding:45px;text-align:center;color:#77999e}.school-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px}.school-node{padding:16px;border:1px solid #2d6370;background:#072029}.school-node h3{font:20px Georgia,serif}.counts{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:14px 0}.counts div{padding:7px;background:#03151b;text-align:center;font:10px monospace}.counts b{display:block;color:var(--cyan);font-size:17px}.hierarchy{display:grid;grid-template-columns:330px 1fr;gap:14px}.node-list{max-height:590px;overflow:auto}.node-select{width:100%;padding:12px;border:0;border-bottom:1px solid #234b55;background:#071d25;color:#dffff7;text-align:left}.node-select:hover,.node-select.active{background:#104137;color:#6fffd8}.tree-panel{padding:18px;border:1px solid #2d5963;background:#061a22}.tree-people{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.tree-group{padding:12px;background:#09242c}.tree-group h4{color:var(--amber);font:13px monospace;text-transform:uppercase}.tree-group li{margin:6px 0;color:#bdd3d1;font-size:12px}.class-node{margin:8px 0;padding:11px;border-left:2px solid var(--cyan);background:#06141a}.toast-stack{position:fixed;right:18px;top:88px;z-index:2200;display:grid;gap:9px;width:min(390px,calc(100vw - 30px));pointer-events:none}.sys-toast{display:grid;grid-template-columns:auto 1fr auto;gap:11px;padding:13px;border:1px solid #39e7bb;background:#061c24f7;box-shadow:0 16px 45px #000b;pointer-events:auto;animation:toastIn .25s}.sys-toast.error{border-color:#ff607b}.sys-toast.warning{border-color:#ffc84d}.sys-toast button{border:0;background:transparent;color:#adc5c5}.sys-toast strong{display:block}.sys-toast p{margin:3px 0 0;color:#a7c2c3;font-size:12px}@keyframes toastIn{from{opacity:0;transform:translateX(20px)}}.master-modal{position:fixed;inset:0;z-index:2300;display:grid;place-items:center;padding:20px;background:#01090dd9;backdrop-filter:blur(7px)}.master-modal[hidden]{display:none}.modal-box{width:min(700px,100%);max-height:90vh;overflow:auto;border:1px solid var(--cyan);background:#071c24;box-shadow:0 0 70px #00dcb52b}.modal-head{display:flex;justify-content:space-between;padding:16px 18px;border-bottom:1px solid #2f5c65}.modal-head h3{margin:0;font:24px Georgia,serif}.modal-body{padding:18px}.modal-foot{display:flex;justify-content:flex-end;gap:9px;padding:14px 18px;border-top:1px solid #2f5c65}.modal-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;margin-bottom:6px;color:#8fc1c3;font:11px monospace;text-transform:uppercase}.span-2{grid-column:1/-1}.audit-action{font-family:monospace;color:#73fbd6}@media(max-width:900px){.telemetry,.command-grid{grid-template-columns:repeat(2,1fr)}.hierarchy{grid-template-columns:1fr}.tree-people{grid-template-columns:1fr}.filters{grid-template-columns:1fr}}@media(max-width:560px){.telemetry,.command-grid,.modal-grid{grid-template-columns:1fr}.span-2{grid-column:auto}}
