@push('scripts')
<script>
(()=>{const CSRF='{{ csrf_token() }}',work=document.getElementById('master-workspace'),state={schools:[],users:{},selected:null},roles={profesores:'Profesor','administradores-colegio':'AdministradorColegio',alumnos:'Alumno'},labels={Profesor:'Profesores',AdministradorColegio:'Administradores de colegio',Alumno:'Alumnos'};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),full=u=>u?.nombre_completo||u?.nombre||'Sin nombre';
async function api(url,o={}){const h={Accept:'application/json',...(o.body?{'Content-Type':'application/json'}:{}),...(o.headers||{})};if(o.method&&o.method!=='GET')h['X-CSRF-TOKEN']=CSRF;const r=await fetch(url,{...o,headers:h}),d=await r.json().catch(()=>({}));if(!r.ok||d.success===false)throw new Error(d.message||Object.values(d.errors||{}).flat()[0]||'Operación rechazada.');return d}
function toast(t,m,type='success'){const e=document.createElement('div');e.className='sys-toast '+type;e.innerHTML=`<i class="fas ${type==='error'?'fa-triangle-exclamation':type==='warning'?'fa-shield-halved':'fa-circle-check'}"></i><div><strong>${esc(t)}</strong><p>${esc(m)}</p></div><button>×</button>`;e.querySelector('button').onclick=()=>e.remove();document.getElementById('toast-stack').append(e);setTimeout(()=>e.remove(),5500)}
function modal(t,b,f){document.getElementById('modal-title').textContent=t;document.getElementById('modal-body').innerHTML=b;document.getElementById('modal-foot').innerHTML=f;document.getElementById('master-modal').hidden=false;setTimeout(()=>document.querySelector('#master-modal input,#master-modal select')?.focus(),30)}function close(){document.getElementById('master-modal').hidden=true}document.querySelector('[data-close]').onclick=close;document.getElementById('master-modal').onclick=e=>{if(e.target.id==='master-modal')close()};
function confirm(t,m,label,run){modal(t,`<p>${esc(m)}</p>`,`<button class="cyber-btn" data-cancel>Cancelar</button><button class="cyber-btn danger" id="confirm-run">${esc(label)}</button>`);document.querySelector('[data-cancel]').onclick=close;document.getElementById('confirm-run').onclick=async()=>{try{await run();close()}catch(e){toast('Operación rechazada',e.message,'error')}}}
async function getSchools(refresh=false){if(refresh||!state.schools.length)state.schools=await api('/api/colegios');return state.schools}function shell(k,t,tools='',body=''){work.innerHTML=`<section class="workspace"><div class="workspace-head"><div><span class="section-kicker">${k}</span><h2>${t}</h2></div>${tools}</div>${body}</section>`}function go(k){location.hash=k}
async function dashboard(){const d=await getSchools(true),n=d.reduce((a,c)=>[a[0]+(+c.administradores_count||0),a[1]+(+c.profesores_count||0),a[2]+(+c.alumnos_count||0)],[0,0,0]);work.innerHTML=`<section class="telemetry">${[['fa-building-shield',d.length,'Nodos institucionales'],['fa-user-shield',n[0],'Administradores'],['fa-chalkboard-user',n[1],'Profesores'],['fa-user-graduate',n[2],'Alumnos']].map(x=>`<div class="metric"><i class="fas ${x[0]}"></i><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</section><section class="command-grid">${[['colegios','fa-building-shield','Registro de colegios','Provisiona y controla nodos.'],['profesores','fa-chalkboard-user','Identidades docentes','Perfiles, credenciales y adscripción.'],['administradores-colegio','fa-user-shield','Administradores','Control institucional.'],['alumnos','fa-user-graduate','Identidades estudiantiles','Cuentas y puntos CodePlay.'],['jerarquia','fa-network-wired','Topología institucional','Inspecciona e imprime jerarquías.'],['auditoria','fa-shield-halved','Auditoría','Traza operaciones sensibles.']].map(x=>`<button class="command" data-go="${x[0]}"><i class="fas ${x[1]}"></i><b>${x[2]}</b><span>${x[3]}</span></button>`).join('')}</section>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}
async function usersView(key){const role=roles[key],[users,schools]=await Promise.all([api('/api/usuarios-por-rol/'+role),getSchools()]);state.users[role]=users;const tools=(role==='Alumno'?'<button class="cyber-btn danger" id="graduate-users"><i class="fas fa-user-graduate"></i>Depurar graduandos</button> ':'')+'<button class="cyber-btn primary" id="new-user"><i class="fas fa-user-plus"></i>Crear identidad</button>';shell('IDENTITY MATRIX // '+role,labels[role],tools,`<div class="filters"><input class="cyber-input" id="q" placeholder="Buscar nombre completo, usuario o correo"><select class="cyber-select" id="school-filter"><option value="">Todos los colegios</option>${schools.map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select><button class="cyber-btn" id="clear">Limpiar</button></div><div id="user-table"></div>`);const render=()=>{const q=document.getElementById('q').value.toLowerCase(),s=document.getElementById('school-filter').value,rows=users.filter(u=>(!s||String(u.colegio_id)===s)&&[full(u),u.nombre,u.email,u.colegio?.nombre].join(' ').toLowerCase().includes(q));document.getElementById('user-table').innerHTML=table(rows,role)};document.getElementById('q').oninput=render;document.getElementById('school-filter').onchange=render;document.getElementById('clear').onclick=()=>{document.getElementById('q').value='';document.getElementById('school-filter').value='';render()};document.getElementById('new-user').onclick=()=>userForm(role);if(role==='Alumno')document.getElementById('graduate-users').onclick=graduationModal;document.getElementById('user-table').onclick=e=>userAction(e,role,key);render()}
function table(rows,role){if(!rows.length)return'<div class="empty-state">Sin coincidencias en la matriz.</div>';return`<div class="data-wrap"><table class="data-grid"><thead><tr><th>Identidad</th><th>Colegio</th><th>Estado</th>${role==='Alumno'?'<th>Puntos CodePlay</th>':''}<th>Clases</th><th>Operaciones</th></tr></thead><tbody>${rows.map(u=>`<tr><td class="identity"><strong>${esc(full(u))}</strong><small>@${esc(u.nombre)}${u.email?' · '+esc(u.email):''}</small></td><td>${esc(u.colegio?.nombre||'Sin asignar')}</td><td><span class="badge-node ${u.activo===false?'off':''}">${u.activo===false?'Bloqueado':'Activo'}</span></td>${role==='Alumno'?`<td>${+u.puntos_totales||0}</td>`:''}<td>${esc((u.clases_como_profesor||u.clases_como_alumno||[]).map(c=>c.nombre).join(', ')||'—')}</td><td><div class="actions"><button class="cyber-btn sm" data-a="edit" data-id="${u.id}"><i class="fas fa-pen"></i></button><button class="cyber-btn sm" data-a="move" data-id="${u.id}"><i class="fas fa-right-left"></i></button><button class="cyber-btn sm warn" data-a="reset" data-id="${u.id}"><i class="fas fa-key"></i></button><button class="cyber-btn sm" data-a="status" data-id="${u.id}"><i class="fas ${u.activo===false?'fa-play':'fa-pause'}"></i></button><button class="cyber-btn sm danger" data-a="delete" data-id="${u.id}"><i class="fas fa-trash"></i></button></div></td></tr>`).join('')}</tbody></table></div>`}
function userAction(e,role,key){const b=e.target.closest('[data-a]');if(!b)return;const u=state.users[role].find(x=>String(x.id)===b.dataset.id);if(b.dataset.a==='edit')userForm(role,u);if(b.dataset.a==='move')moveUser(u,key);if(b.dataset.a==='reset')confirm('Rotar credencial',`Se asignará una clave temporal a ${full(u)}.`,'Restablecer',async()=>{await api(`/api/usuarios/${u.id}/reset-password`,{method:'POST',body:JSON.stringify({nueva_clave:'Ined1234'})});toast('Credencial rotada','Clave temporal: Ined1234','warning')});if(b.dataset.a==='status')confirm('Cambiar estado',`${u.activo===false?'Activar':'Bloquear'} a ${full(u)}.`,'Confirmar',async()=>{await api(`/api/usuarios/${u.id}/estado`,{method:'PATCH',body:JSON.stringify({activo:u.activo===false})});toast('Estado sincronizado','Identidad actualizada.');usersView(key)});if(b.dataset.a==='delete')confirm('Eliminar identidad',`Se eliminará permanentemente a ${full(u)}. La operación no se puede deshacer.`,'Eliminar',async()=>{await api(`/api/usuarios/${u.id}`,{method:'DELETE'});toast('Identidad eliminada','Registro retirado.','warning');usersView(key)})}
async function userForm(role,u=null){const schools=await getSchools();modal(u?'Editar identidad':'Provisionar identidad',`<form id="user-form" class="modal-grid"><div class="field span-2"><label>Nombre completo</label><input class="cyber-input" name="nombre_completo" required value="${esc(full(u)||'')}"></div><div class="field"><label>Nombre de usuario</label><input class="cyber-input" name="nombre" required value="${esc(u?.nombre||'')}"></div><div class="field"><label>Correo ${role==='Alumno'?'(opcional)':''}</label><input class="cyber-input" type="email" name="email" value="${esc(u?.email||'')}" ${role==='Alumno'?'':'required'}></div>${u?'':`<div class="field"><label>Colegio</label><select class="cyber-select" name="colegio_id" required><option value="">Seleccionar nodo</option>${schools.filter(c=>c.activo).map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select></div><div class="field"><label>Clave temporal</label><input class="cyber-input" name="clave" value="CodePlay2026" required></div><div class="field"><label>Clase (opcional)</label><select class="cyber-select" name="clase_id"><option value="">Asignación automática</option></select></div>${role==='Alumno'?'<div class="field"><label>Profesor (opcional)</label><select class="cyber-select" name="profesor_id"><option value="">Sin asignación específica</option></select></div>':''}`}</form>`,`<button class="cyber-btn" data-cancel>Cancelar</button><button class="cyber-btn primary" id="save-user">Guardar</button>`);document.querySelector('[data-cancel]').onclick=close;if(!u)document.querySelector('[name=colegio_id]').onchange=async e=>{if(!e.target.value)return;const d=await api(`/api/colegios/${e.target.value}/resumen`);document.querySelector('[name=clase_id]').innerHTML='<option value="">Asignación automática</option>'+d.clases.map(c=>`<option value="${c.id}">${esc(c.nombre)}${c.ciclo_escolar?' · '+c.ciclo_escolar:''}</option>`).join('');const p=document.querySelector('[name=profesor_id]');if(p)p.innerHTML='<option value="">Sin asignación específica</option>'+d.profesores.map(x=>`<option value="${x.id}">${esc(full(x))}</option>`).join('')};document.getElementById('save-user').onclick=async()=>{const f=document.getElementById('user-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.rol=role;Object.keys(d).forEach(k=>d[k]===''&&delete d[k]);try{await api(u?`/api/usuarios/${u.id}`:'/api/usuarios',{method:u?'PUT':'POST',body:JSON.stringify(d)});close();toast(u?'Perfil sincronizado':'Identidad provisionada','Cambios aplicados.');usersView(Object.keys(roles).find(k=>roles[k]===role))}catch(e){toast('No fue posible guardar',e.message,'error')}}}
async function moveUser(u,key){const s=await getSchools();modal('Migrar identidad',`<p>Mover <strong>${esc(full(u))}</strong>. Sus asignaciones se reconstruirán en el destino.</p><select class="cyber-select" id="move-school">${s.filter(c=>c.activo&&c.id!==u.colegio_id).map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select>`,`<button class="cyber-btn" data-cancel>Cancelar</button><button class="cyber-btn warn" id="move-run">Migrar</button>`);document.querySelector('[data-cancel]').onclick=close;document.getElementById('move-run').onclick=async()=>{try{await api(`/api/usuarios/${u.id}/colegio`,{method:'PATCH',body:JSON.stringify({colegio_id:document.getElementById('move-school').value})});close();toast('Migración completada','Identidad reasignada.');usersView(key)}catch(e){toast('Migración detenida',e.message,'error')}}}
async function graduationModal(){const schools=await getSchools();modal('Depurar alumnos graduandos',`<p>Selecciona el colegio y ciclo. Antes de eliminar podrás marcar los repitentes que deben conservarse.</p><div class="modal-grid"><div class="field"><label>Colegio</label><select class="cyber-select" id="g-school"><option value="">Seleccionar nodo</option>${schools.map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select></div><div class="field"><label>Ciclo escolar</label><select class="cyber-select" id="g-cycle" disabled><option value="">Seleccionar ciclo</option></select></div><div class="field span-2"><label>Clase o ciclo completo</label><select class="cyber-select" id="g-class" disabled><option value="">Todo el ciclo</option></select></div></div><div id="g-results"></div>`,`<button class="cyber-btn" data-cancel>Cancelar</button><button class="cyber-btn primary" id="g-review">Revisar alumnos</button>`);document.querySelector('[data-cancel]').onclick=close;let topology=null;document.getElementById('g-school').onchange=async e=>{const cycle=document.getElementById('g-cycle');cycle.disabled=true;if(!e.target.value)return;topology=await api(`/api/colegios/${e.target.value}/resumen`);const cycles=[...new Set(topology.clases.map(c=>String(c.ciclo_escolar||'')).filter(Boolean))].sort().reverse();cycle.innerHTML='<option value="">Seleccionar ciclo</option>'+cycles.map(x=>`<option>${esc(x)}</option>`).join('');cycle.disabled=false};document.getElementById('g-cycle').onchange=e=>{const cls=document.getElementById('g-class'),rows=(topology?.clases||[]).filter(c=>String(c.ciclo_escolar)===e.target.value);cls.innerHTML='<option value="">Todo el ciclo</option>'+rows.map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('');cls.disabled=false};document.getElementById('g-review').onclick=async()=>{const school=document.getElementById('g-school').value,cycle=document.getElementById('g-cycle').value,cls=document.getElementById('g-class').value;if(!school||!cycle){toast('Datos incompletos','Selecciona colegio y ciclo escolar.','warning');return}try{const d=await api(`/api/master/alumnos-graduandos?colegio_id=${school}&ciclo_escolar=${encodeURIComponent(cycle)}${cls?'&clase_id='+cls:''}`);document.getElementById('g-results').innerHTML=`<div style="margin-top:18px;border-top:1px solid #315d66;padding-top:15px"><strong>${d.total} alumnos detectados</strong><p>Marca únicamente los repitentes que deben conservarse.</p><div style="max-height:260px;overflow:auto">${d.alumnos.map(u=>`<label style="display:flex;gap:10px;padding:8px;border-bottom:1px solid #21434b"><input type="checkbox" class="g-keep" value="${u.id}"><span>${esc(full(u))}<small style="display:block;color:#7d9da1">@${esc(u.nombre)}</small></span></label>`).join('')||'<p>Sin alumnos en este alcance.</p>'}</div><label style="display:flex;gap:9px;margin-top:12px;color:#ffcf59"><input type="checkbox" id="g-checked">Confirmo que revisé y marqué todos los repitentes.</label><button class="cyber-btn danger" id="g-delete" style="margin-top:12px" disabled>Eliminar graduandos</button></div>`;document.getElementById('g-checked').onchange=e=>document.getElementById('g-delete').disabled=!e.target.checked||!d.total;document.getElementById('g-delete').onclick=()=>{const keep=[...document.querySelectorAll('.g-keep:checked')].map(x=>+x.value);confirm('Confirmar depuración',`Se eliminarán ${d.total-keep.length} alumnos y se conservarán ${keep.length} repitentes.`,'Eliminar definitivamente',async()=>{const result=await api('/api/master/alumnos-graduandos',{method:'DELETE',body:JSON.stringify({colegio_id:+school,ciclo_escolar:cycle,clase_id:cls?+cls:null,conservar_alumnos:keep})});toast('Depuración completada',result.message,'warning');usersView('alumnos')})}}catch(e){toast('No fue posible consultar',e.message,'error')}}}
async function collegesView(){const data=await getSchools(true);shell('INSTITUTION REGISTRY // NODES','Colegios',`<button class="cyber-btn primary" id="new-school"><i class="fas fa-plus"></i>Provisionar colegio</button>`,`<div class="filters"><input class="cyber-input" id="sq" placeholder="Buscar nombre o código"><select class="cyber-select" id="ss"><option value="">Todos</option><option value="1">Activos</option><option value="0">Desactivados</option></select><button class="cyber-btn" id="sc">Limpiar</button></div><div class="school-grid" id="school-grid"></div>`);const draw=()=>{const q=document.getElementById('sq').value.toLowerCase(),s=document.getElementById('ss').value;document.getElementById('school-grid').innerHTML=data.filter(c=>(!s||String(+!!c.activo)===s)&&`${c.nombre} ${c.codigo}`.toLowerCase().includes(q)).map(c=>`<article class="school-node"><span class="badge-node ${c.activo?'':'off'}">${c.activo?'ONLINE':'OFFLINE'}</span><h3>${esc(c.nombre)}</h3><code>${esc(c.codigo)}</code><div class="counts"><div><b>${c.administradores_count}</b>Admins</div><div><b>${c.profesores_count}</b>Docs</div><div><b>${c.alumnos_count}</b>Alumnos</div><div><b>${c.clases_count}</b>Clases</div></div><div class="actions"><button class="cyber-btn sm" data-sa="tree" data-id="${c.id}">Topología</button><button class="cyber-btn sm" data-sa="edit" data-id="${c.id}">Editar</button><button class="cyber-btn sm warn" data-sa="status" data-id="${c.id}">${c.activo?'Desactivar':'Activar'}</button><button class="cyber-btn sm danger" data-sa="delete" data-id="${c.id}">×</button></div></article>`).join('')||'<div class="empty-state">Sin nodos.</div>'};document.getElementById('sq').oninput=draw;document.getElementById('ss').onchange=draw;document.getElementById('sc').onclick=()=>{document.getElementById('sq').value='';document.getElementById('ss').value='';draw()};document.getElementById('new-school').onclick=()=>schoolForm();document.getElementById('school-grid').onclick=e=>{const b=e.target.closest('[data-sa]');if(!b)return;const c=data.find(x=>String(x.id)===b.dataset.id);if(b.dataset.sa==='tree'){state.selected=c.id;go('jerarquia')}if(b.dataset.sa==='edit')schoolForm(c);if(b.dataset.sa==='status')confirm('Cambiar nodo',`${c.activo?'Desactivar':'Activar'} ${c.nombre}.`,'Confirmar',async()=>{await api(`/api/colegios/${c.id}`,{method:'PUT',body:JSON.stringify({activo:!c.activo})});toast('Nodo sincronizado','Estado actualizado.');collegesView()});if(b.dataset.sa==='delete')confirm('Destruir nodo',`Solo puede eliminarse ${c.nombre} si está vacío.`,'Eliminar',async()=>{await api(`/api/colegios/${c.id}`,{method:'DELETE'});toast('Nodo eliminado','Colegio retirado.','warning');collegesView()})};draw()}
function schoolForm(c=null){modal(c?'Editar nodo':'Provisionar colegio',`<div class="field"><label>Nombre institucional</label><input class="cyber-input" id="school-name" maxlength="150" value="${esc(c?.nombre||'')}"></div>`,`<button class="cyber-btn" data-cancel>Cancelar</button><button class="cyber-btn primary" id="save-school">Guardar</button>`);document.querySelector('[data-cancel]').onclick=close;document.getElementById('save-school').onclick=async()=>{try{await api(c?`/api/colegios/${c.id}`:'/api/colegios',{method:c?'PUT':'POST',body:JSON.stringify({nombre:document.getElementById('school-name').value})});close();toast('Nodo sincronizado','Registro guardado.');collegesView()}catch(e){toast('No fue posible guardar',e.message,'error')}}}
async function hierarchyView(){const all=await getSchools();shell('TOPOLOGY EXPLORER // PRINTABLE','Jerarquías de colegio','',`<div class="filters"><input class="cyber-input" id="tq" placeholder="Filtrar por nombre de colegio"><div></div><button class="cyber-btn" id="tc">Limpiar</button></div><div class="hierarchy"><div class="node-list" id="tree-list"></div><div class="tree-panel" id="tree-panel"><div class="empty-state">Selecciona un nodo.</div></div></div>`);const list=()=>{const q=document.getElementById('tq').value.toLowerCase();document.getElementById('tree-list').innerHTML=all.filter(c=>c.nombre.toLowerCase().includes(q)).map(c=>`<button class="node-select ${String(state.selected)===String(c.id)?'active':''}" data-tree="${c.id}"><strong>${esc(c.nombre)}</strong><br><small>${esc(c.codigo)} · ${c.activo?'ONLINE':'OFFLINE'}</small></button>`).join('')||'<div class="empty-state">Sin coincidencias.</div>';document.querySelectorAll('[data-tree]').forEach(b=>b.onclick=()=>load(b.dataset.tree))};document.getElementById('tq').oninput=list;document.getElementById('tc').onclick=()=>{document.getElementById('tq').value='';list()};list();if(state.selected)load(state.selected);async function load(id){state.selected=id;list();const d=await api(`/api/colegios/${id}/resumen`),group=(t,x)=>`<div class="tree-group"><h4>${t} // ${x.length}</h4><ul>${x.map(u=>`<li>${esc(full(u))}<br><small>@${esc(u.nombre)}</small></li>`).join('')||'<li>Sin registros</li>'}</ul></div>`;document.getElementById('tree-panel').innerHTML=`<div class="workspace-head"><div><span class="section-kicker">${esc(d.colegio.codigo)}</span><h2>${esc(d.colegio.nombre)}</h2></div><a class="cyber-btn primary" target="_blank" href="/master/colegios/${id}/jerarquia/imprimir"><i class="fas fa-print"></i>Imprimir jerarquía filtrada</a></div><div class="tree-people">${group('Administradores',d.administradores)}${group('Profesores',d.profesores)}${group('Alumnos',d.alumnos)}</div><h3 style="margin-top:18px">Clases // ${d.clases.length}</h3>${d.clases.map(c=>`<div class="class-node"><strong>${esc(c.nombre)}</strong> · ${c.profesores_count} profesor(es) · ${c.alumnos_count} alumno(s)<br><small>${esc(c.profesores.map(full).join(', ')||'Sin docente')}</small></div>`).join('')||'<div class="empty-state">Sin clases.</div>'}`}}
async function auditView(){const all=await getSchools();shell('IMMUTABLE ACTIVITY STREAM // AUDIT','Auditoría operativa','',`<div class="filters"><input class="cyber-input" id="aq" placeholder="Filtrar acción, actor u objetivo"><select class="cyber-select" id="as"><option value="">Todos los colegios</option>${all.map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select><button class="cyber-btn" id="ar">Actualizar</button></div><div id="audit-table"></div>`);async function load(){const id=document.getElementById('as').value,d=await api('/api/auditoria?limite=100'+(id?'&colegio_id='+id:''));const draw=()=>{const q=document.getElementById('aq').value.toLowerCase(),r=d.data.filter(x=>[x.accion,x.actor?.nombre,x.objetivo_usuario?.nombre,x.colegio?.nombre].join(' ').toLowerCase().includes(q));document.getElementById('audit-table').innerHTML=`<div class="data-wrap"><table class="data-grid"><thead><tr><th>Timestamp</th><th>Actor</th><th>Operación</th><th>Objetivo</th><th>Nodo</th></tr></thead><tbody>${r.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.actor?.nombre||'Eliminado')}</td><td class="audit-action">${esc(x.accion)}</td><td>${esc(x.objetivo_usuario?.nombre||x.entidad_tipo||'—')}</td><td>${esc(x.colegio?.nombre||'—')}</td></tr>`).join('')}</tbody></table></div>`};document.getElementById('aq').oninput=draw;draw()}document.getElementById('as').onchange=load;document.getElementById('ar').onclick=load;load()}
async function route(){const k=location.hash.slice(1)||'dashboard';try{if(k==='dashboard')await dashboard();else if(roles[k])await usersView(k);else if(k==='colegios')await collegesView();else if(k==='jerarquia')await hierarchyView();else if(k==='auditoria')await auditView();else go('dashboard')}catch(e){shell('SYSTEM FAULT','Módulo no disponible','',`<div class="empty-state">${esc(e.message)}</div>`);toast('Fallo de sincronización',e.message,'error')}}setInterval(()=>document.getElementById('system-clock').textContent=new Date().toLocaleString('es-GT',{hour12:false})+' // GT',1000);addEventListener('hashchange',route);route()})();
</script>
@endpush
